/* Unit tests for js/sm/mergeBot.js — the event-driven merge fast path. */
/* global loadModule, assert, test, suite, makeRequire */

function fixture(opts) {
    opts = opts || {};
    var calls = { merges: [], adds: [], removes: [], comments: [], cli: [] };
    var checkRuns = opts.checkRuns || [
        { status: 'COMPLETED', conclusion: 'SUCCESS' }
    ];
    var mergeResponses = opts.mergeResponses || [
        JSON.stringify({ merged: true })
    ];
    var pr = {
        number: opts.number || 42,
        state: 'OPEN',
        draft: opts.draft === true,
        mergeable: opts.mergeable !== undefined ? opts.mergeable : true,
        mergeable_state: opts.mergeableState || 'clean',
        head: { sha: opts.headSha || 'deadbeef' },
        statusCheckRollup: opts.statusCheckRollup || undefined,
        labels: (opts.labels || ['ai_validating']).map(function (n) {
            return { name: n };
        })
    };
    var wfCalls = [];
    var crCalls = [];
    var listCalls = [];
    var mods = {
        github_list_workflow_runs: function (a) {
            wfCalls.push(a);
            return JSON.stringify({ workflow_runs: opts.workflowRuns || [] });
        },
        github_list_prs: function (a) {
            listCalls.push(a);
            // gh-952: state-aware list (open/merged) for the multi-PR
            // slot-holder scenarios. prIndex maps state → raw REST list
            // payload; absent, the legacy single-PR shape is served.
            if (opts.prIndex) {
                var state = (a && a.state) || 'open';
                return JSON.stringify(opts.prIndex[state] || []);
            }
            return JSON.stringify([{ number: pr.number }]);
        },
        github_get_pr: function (a) {
            if (opts.prByNumber) {
                return JSON.stringify(opts.prByNumber[a.pullRequestId] || { state: 'OPEN' });
            }
            return JSON.stringify(pr);
        },
        github_get_commit_check_runs: function (a) {
            // The Dart tool requires workspace/repository — a bare
            // {commitSha} call dies with 'Required parameter workspace is
            // missing' and the whole merge leg crashes (live 2026-09-29).
            // Assert in the test body, not here: mocks run in the module
            // scope, where `assert` is not a global.
            crCalls.push(a);
            if (opts.checkRunsByNumber && opts.checkRunsByNumber[a.commitSha] !== undefined) {
                return JSON.stringify({ check_runs: opts.checkRunsByNumber[a.commitSha] });
            }
            return JSON.stringify({ check_runs: checkRuns });
        },
        github_merge_pr: function (m) {
            calls.merges.push(m);
            return mergeResponses[Math.min(calls.merges.length - 1, mergeResponses.length - 1)];
        },
        github_add_labels: function (a) { calls.adds.push(a); return '{}'; },
        github_remove_label: function (r) { calls.removes.push(r); return '{}'; },
        // Self-tick (owner rule 2026-10-04): capture every cli dispatch;
        // opts.cliThrows simulates a dead gh CLI for the failure path.
        cli_execute_command: function (c) {
            calls.cli.push(c);
            if (opts.cliThrows) throw new Error(opts.cliThrows);
            return '';
        }
    };
    var bot = loadModule('js/sm/mergeBot.js', makeRequire({}), mods);
    return { bot: bot, calls: calls, mods: mods, wfCalls: wfCalls, crCalls: crCalls, listCalls: listCalls };
}

suite('mergeBot', function () {
---
    // Live fa 2026-10-17 06:30–08:10Z: PR #1661 was merged by the OWNER via
    // bypass while its validation was ARMED (Quality gate / Binaries smoke
    // pending stamps at 06:04Z). The machine's merge path never ran, so the
    // arm was never consumed — and the merged PR vanished from the open
    // list the bot scans. From then on the bot logged every approved PR as
    // '⏳ FIFO-queued (awaiting validate-armed turn)' with acted: 0: the
    // slot bookkeeping saw neither a holder (it merged) nor a released
    // slot, and the queue starved behind a holder that will NEVER validate
    // again. gh-766 taught the bot to advance past a dead head it can SEE;
    // gh-952 extends the same remedy to the dead head it cannot see: the
    // armed holder whose PR already merged.

    // Multi-PR fixture with a STATE-AWARE PR list: openPrs/mergedPrs are
    // raw REST list payloads (labels included), prByNumber serves the
    // per-number get_pr bodies. Same mock surface as queueFixture above.
    function slotFixture(openPrs, mergedPrs) {
        var calls = { merges: [], adds: [], removes: [], cli: [] };
        var byNumber = {};
        openPrs.concat(mergedPrs || []).forEach(function (p) { byNumber[p.number] = p; });
        var byHead = {};
        openPrs.forEach(function (p) { byHead[p.headSha] = p; });
        var labelObjs = function (p) {
            return (p.labels || []).map(function (n) { return { name: n }; });
        };
        var listCalls = [];
        var mods = {
            github_list_workflow_runs: function () {
                return JSON.stringify({ workflow_runs: [] });
            },
            github_list_prs: function (a) {
                listCalls.push(a);
                var state = (a && a.state) || 'open';
                var src = state === 'merged' ? (mergedPrs || []) : openPrs;
                return JSON.stringify(src.map(function (p) {
                    return { number: p.number, labels: labelObjs(p),
                             head: { sha: p.headSha }, merged_at: p.merged_at };
                }));
            },
            github_get_pr: function (a) {
                var p = byNumber[a.pullRequestId] || {};
                return JSON.stringify({
                    number: p.number, state: 'OPEN', draft: false, mergeable: true,
                    mergeable_state: p.mergeableState || 'clean',
                    head: { sha: p.headSha }, labels: labelObjs(p)
                });
            },
            github_get_commit_check_runs: function (a) {
                var p = byHead[a.commitSha] || {};
                return JSON.stringify({ check_runs: p.checkRuns || [] });
            },
            github_merge_pr: function (m) { calls.merges.push(m); return JSON.stringify({ merged: true }); },
            github_add_labels: function (a) { calls.adds.push(a); return '{}'; },
            github_remove_label: function (r) { calls.removes.push(r); return '{}'; },
            cli_execute_command: function (c) { calls.cli.push(c); return ''; }
        };
        var bot = loadModule('js/sm/mergeBot.js', makeRequire({}), mods);
        return { bot: bot, calls: calls, listCalls: listCalls };
    }

    var GREEN = [{ status: 'COMPLETED', conclusion: 'SUCCESS' }];
    function hoursAgoIso(h) {
        return new Date(Date.now() - h * 60 * 60 * 1000).toISOString();
    }
    // The externally-merged slot holder: merged 1h ago, the merge-window
    // arm labels still on it (labels outlive the merge).
    function mergedHolder(hoursAgo) {
        return { number: 1661, labels: ['ai_validating', 'pr_approved'],
                 headSha: 'sha1661', merged_at: hoursAgoIso(hoursAgo || 1) };
    }

    test('recently-merged armed holder → slot released: the release is logged and the merged probe is scoped to this repo', function () {
        var fx = slotFixture([
            { number: 1563, labels: ['pr_approved'], headSha: 'sha1563', checkRuns: GREEN },
            { number: 1564, labels: ['pr_approved'], headSha: 'sha1564', checkRuns: GREEN }
        ], [mergedHolder(1)]);
        var result = fx.bot.action({ jobParams: { repo: 'o/r' } });

        assert.ok(result.log.some(function (l) {
            return l.indexOf('pr-1661') !== -1 && l.indexOf('MERGED') !== -1 &&
                   l.indexOf('slot released') !== -1;
        }), 'the operator sees WHICH PR held the slot and that it merged: ' + JSON.stringify(result.log));

/**
 * mergeBot — event-driven fast path for the machine loop's merge stage.
 *
 * The SM tick (cron every-10-minutes) is best-effort: GitHub silently drops scheduled
 * runs under load (live: fa ticks vanished for 30+ min while approved
 * green PRs waited). This bot runs on EVENTS — CI conclusion
 * (workflow_run), label changes / head pushes (pull_request), check-run
 * completions, and manual dispatch — and performs exactly the
 * deterministic, idempotent stage transitions that need no orchestration:
 *
 *   approved + ai_validating + green + CLEAN  -> squash-merge (retry once
 *                                                on transient API errors)
 *   ai_validating + green + CLEAN + !approved-> latch ai_validated, unarm
 *   ai_validating + green + base moved       -> unarm (stale head; the SM
 *                                                refreshes + re-validates)
 *
 * Everything else (validation dispatch, review/rework legs, conflict
 * rework, fail-validation reporting) stays SM-owned: the bot never
 * dispatches workflows, never arms labels beyond the two latches above —
 * it only CONCLUDES stages whose evidence is already on the PR.
 *
 * One exception (owner rule 2026-10-04): a deferred approved PR with
 * acted==0 at end-of-run fires a single machine-sm.yml tick (self-heal,
 * 'gh workflow run machine-sm.yml -F dryRun=false --repo owner/name'),
 * skipped when a machine-sm.yml run is already active — see the
 * END-OF-RUN SELF-TICK block in action() and hasActiveSmRun().
 *
 * jsrunner contract: repo comes from params.jobParams.repo
 * ("owner/name") or GH_REPO; tools are the global snake_case bridge.
 */

/* global github_list_prs, github_get_pr, github_get_commit_check_runs,
   github_list_workflow_runs, github_merge_pr, github_add_labels,
   github_remove_label, cli_execute_command */

function parseMcp(raw) {
    if (raw === null || raw === undefined) return {};
    if (typeof raw === 'object') return raw;
    try { return JSON.parse(String(raw)); } catch (e) { return {}; }
}

function labelNames(pr) {
    return (pr.labels || []).map(function (l) { return (l && l.name) || l; });
}

/**
 * Epoch ms when the run started waiting (check-run started_at, workflow-run
 * created_at) or null when the payload carries no usable timestamp — the
 * gh-766 stale-head detection FAILS OPEN on null (treated as live).
 */
function pendingStartedAt(r) {
    if (!r) return null;
    var raw = r.started_at || r.startedAt || r.created_at || r.createdAt;
    if (!raw) return null;
    var ts = Date.parse(raw);
    return isNaN(ts) ? null : ts;
}

/**
 * Same rollup as checksRollup, plus pendingSince: the OLDEST start time
 * among the pending evidence (gh-766) — an armed head whose checks have
 * been motionless past staleHeadMinutes is a dead FIFO head (skipped with
 * an explicit log line, unarmed, queue advances) instead of an eternal
 * 'checks=pending — waiting'.
 */
function rollupDetail(commitSha, pr, job, owner, name) {
    var cr = parseMcp(github_get_commit_check_runs({
        workspace: owner, repository: name, commitSha: commitSha
    }));
    var runs = cr.check_runs || cr.total_count !== undefined ? (cr.check_runs || []) : [];
    if (!runs.length && pr && Array.isArray(pr.statusCheckRollup) && pr.statusCheckRollup.length) {
        runs = pr.statusCheckRollup;
    }
    if (!runs.length) {
        // Workflow-run fallback (live: fa #762): the REST PR body has NO
        // statusCheckRollup (GraphQL-only) and API silent-updated heads carry
        // no check runs — but the SM-dispatched CI run IS on this exact sha.
        // Read the repo's CI workflow runs and match head_sha. The SM's own
        // waiter is a pull_request-event job: it never re-runs on refreshed
        // heads, so this is the ONLY conclusive evidence for them.
        var wf = parseMcp(github_list_workflow_runs({
            workspace: owner, repository: name,
            workflowId: (job && job.ciWorkflow) || 'ci.yml', perPage: 30
