    var pipes = (gitlab_get_mr_pipelines({ workspace: owner, repository: repo, pullRequestId: String(mrNumber) }) || {});
    var list = pipes.pipelines || pipes || [];
    var red = false, pending = false, any = false, cancelled = 0;
